      "summary": "首页 > 科研进展 近日，中国科学院合肥物质科学研究院在高负载厚电极及锌离子混合电容器研究方面取得进展，提出顺序激光工程策略，构筑一体化阶梯式功能梯度厚电极，实现厚电极内部不同功能区域的空间协同调控。 锌离子混合电容器具有较高能量密度、快速充放电和本征安全等优势，在高功率储能领域具有应用潜力。提升电极负载可有效提升容量",
