      "angle": "Report beyond the announcement: verify yield, scale, customers and how manufacturing capability and bottlenecks affects industrial resilience. For this item, test the claim behind “印度喊话“芯片走向世界”，但还没证明能生产28nm” against primary-source evidence.",
