      "matchedTopic": "半导体供应链",
      "rawText": "首页 风闻 财经 国际 军事 观出行 观金融 产经 科技 城事 滚动 观察员 视频 印度喊话“芯片走向世界”，但还没证明能生产28nm 赖家琪 （文/赖家琪 编辑/吕栋） 当地时间9月17日，第五届印度半导体展览会（SEMICON India）在新德里开幕，印度总理莫迪亲自到场揭幕。 通过这场展会，印度试图向外界展示一个不断壮大的半导体产业：不仅能制造芯片，还具备一个覆盖设计、制造、封装、材料、研发和人才的完整生态。借此，印度希望将自己融入全球半导体供应链，成为其中的关键一环。 不过，印度想要成为全球半导体制造中心，仍面临诸多现实挑战。虽然该国在芯片设计领域有优势，但芯片制造是完全不同的挑战，需要巨额投资、稳定的电力供应等基础设施，以及由硅晶圆和精密设备供应商组成的庞大产业网络，而在这些方面印度都存在短板。 印度的半导体雄心始于2021年的“印度半导体使命”。在此基础上，该国2022年投入7600亿卢比（约合531.6亿元人民币）推出了“印度半导体计划”（Semicon India Programme），又称“Semicon 1.0”。 今年7月，印度又批准了一项规模达1.275万亿卢",
